<template>
  <v-container class="site-page site-page--readable site-stack">
    <SitePageHeader :summary="titles.faqDescription" :title="titles.faqPage"/>
    <v-card class="site-card" flat>
      <section :aria-label="titles.faqPage" class="site-card__body faq-list">
        <article :key="index" class="faq-item" v-for="(item, index) in faqItems">
          <h2 class="site-section-title faq-item__question">{{ item.question }}</h2>
          <p class="site-body faq-item__answer">{{ item.answer }}</p>
        </article>
      </section>
    </v-card>
  </v-container>
</template>

<style lang="stylus" scoped>
.faq-list
  display flex
  flex-direction column
  gap 28px

.faq-item__question
  margin 0 0 8px

.faq-item__answer
  margin 0
  max-width 820px
</style>

<script lang="ts">
import {Component} from 'vue-property-decorator'
import PortalPageBase from '@/view/PortalPageBase'
import SitePageHeader from '@/view/SitePageHeader.vue'
import {breadcrumbList, canonicalUrl, organizationReference, organizationStub, pageMetaInfo, socialCardPath} from '@/model/Seo'
import {brandName} from '@/model/Brand'
import {Locale} from '@/model/content/Locale'

@Component({components: {SitePageHeader}})
export default class FAQ extends PortalPageBase {
  pageTitle = this.titles.faqPage

  get faqItems() {
    const titles = this.titles
    return [
      {question: titles.faqQ1, answer: titles.faqA1},
      {question: titles.faqQ2, answer: titles.faqA2},
      {question: titles.faqQ3, answer: titles.faqA3},
      {question: titles.faqQ4, answer: titles.faqA4},
      {question: titles.faqQ5, answer: titles.faqA5},
      {question: titles.faqQ6, answer: titles.faqA6},
      {question: titles.faqQ7, answer: titles.faqA7}
    ]
  }

  metaInfo(): any {
    const structuredData = {
      '@context': 'https://schema.org',
      '@graph': [
        {
          '@type': 'FAQPage',
          name: this.titles.faqPage,
          description: this.titles.faqDescription,
          url: canonicalUrl(this.constants.faqPath),
          inLanguage: Locale.active,
          about: organizationReference(),
          mainEntity: this.faqItems.map(item => ({
            '@type': 'Question',
            name: item.question,
            acceptedAnswer: {'@type': 'Answer', text: item.answer}
          }))
        },
        organizationStub(),
        breadcrumbList([
          {name: brandName, path: '/'},
          {name: this.titles.faqPage, path: this.constants.faqPath}
        ])
      ]
    }
    return pageMetaInfo(
      this.titles.faqSeoTitle,
      this.titles.faqDescription,
      this.constants.faqPath,
      socialCardPath(this.constants.faqPath),
      structuredData
    )
  }

  beforeRouteEnter(to: any, from: any, next: any) {
    super.beforeRouteEnter(to, from, next)
  }
}
</script>
